# ---------------------------------------------------------------- G5 "how many times greater"
def fmtn(n): return ("%d" % n) if n < 10000 else ("{:,}".format(n).replace(",", "\\,"))
def times(a, b, key, d_sub):
    k = int(key); lo, hi = fmtn(k // 10), fmtn(k * 10); K = fmtn(k)
    small = (r"в $0{,}1$ раз", r"Ученик разделил меньшее число на большее: $%s:%s=0{,}1$; спрашивается, во сколько раз больше первое число." % (b, a))
    return P(r"Во сколько раз число $%s$ больше числа $%s$?" % (a, b), r"в $%s$ раз" % K, [
        (r"в $%s$ раз" % hi, r"Ученик насчитал лишний разряд при сдвиге запятой: $%s:%s=%s$." % (a, b, K)),
        small if k == 10 else (r"в $%s$ раз" % lo, r"Ученик пропустил один разряд при сдвиге запятой: $%s:%s=%s$." % (a, b, K)),
        (r"на $%s$" % d_sub, r"Ученик нашёл разность (на сколько больше), а спрашивается, во сколько раз больше: нужно разделить.")])
T("G5_TB_62_1478.1", MC, [times(r"153{,}2", r"15{,}32", "10", r"137{,}88"), times(r"153{,}2", r"0{,}1532", "1000", r"153{,}0468"), times(r"153{,}2", r"0{,}01532", "10000", r"153{,}18468")])
T("G5_TB_62_1478.2", MC, [times(r"21{,}7", r"2{,}17", "10", r"19{,}53"), times(r"21{,}7", r"0{,}217", "100", r"21{,}483"), times(r"21{,}7", r"0{,}0217", "1000", r"21{,}6783")])

