# ---------------------------------------------------------------- G6 compare time intervals
CMP = r"Сравните промежутки времени, выразив их в минутах: "
def cmpp(a, b, ma, mb, d):
    return P(CMP + r"$%s$ ч и $%s$ ч." % (a, b), r"$%s$ ч $<%s$ ч ($%d$ мин $<%d$ мин)" % (a, b, ma, mb), d)
